1) Go to the root folder of your godot project:

res://  

2) Create a new script and name it project\_exporter

It should look like project\_exporter.gd 

3) Insert this code inside:

    @tool
    extends EditorScript

    # Settings
    const OUTPUT_FILE = "res://project_summary.txt"
    const INCLUDED_EXTENSIONS = ["gd", "tscn"]
    const SKIP_FOLDERS = [".godot", "addons"]

    func _run():
    var file = FileAccess.open(OUTPUT_FILE, FileAccess.WRITE)
    if not file:
    print("Failed to create output file.")
    return

    print("Starting export...")
    _scan_dir("res://", file)
    file.close()
    print("Export complete! Saved to: ", OUTPUT_FILE)

    func _scan_dir(path: String, output: FileAccess):
    var dir = DirAccess.open(path)
    if not dir: return

    dir.list_dir_begin()
    var file_name = dir.get_next()

    while file_name != "":
    if dir.current_is_dir():
    if not file_name in SKIP_FOLDERS:
    _scan_dir(path + file_name + "/", output)
    else:
    var ext = file_name.get_extension()
    if ext in INCLUDED_EXTENSIONS:
    var full_path = path + file_name
    _write_file_to_output(full_path, output)

    file_name = dir.get_next()

    func _write_file_to_output(file_path: String, output: FileAccess):
    var source_file = FileAccess.open(file_path, FileAccess.READ)
    if source_file:
    output.store_line("\n" + "=".repeat(50))
    output.store_line("FILE: " + file_path)
    output.store_line("=".repeat(50) + "\n")
    output.store_line(source_file.get_as_text())
    source_file.close()



4) Save the script -> right click -> run

5) In the output, you should see:   

"Starting export...Export complete! Saved to: res://project\_summary.txt"

6) The txt file should be available then. Just copy and paste it into any LLM for complete context of your godot project. 

Hope this helps!
